class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change #4: EF 9 uses parameterized queries by default for Cosmos.
        // Raw SQL must use FromSqlRaw (not FromSql) to avoid parameter binding issues.
        // Also, the discriminator property name is preserved as "Discriminator" (see BlogContext).
        var blogs = context.Blogs
            .FromSqlRaw("SELECT * FROM c WHERE c.Discriminator = 'Blog'")
            .ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change #5: EF 9 uses patch-based (partial) updates by default.
        // Full-document replace semantics require opt-in if needed:
        //   context.Database.UseFullDocumentUpdates();
        // Patch updates are fine here (only Name changes), so no action needed.
        context.SaveChanges();
    }
}

